import { useState, useEffect } from 'react'

const KEY = 'cloakcash_ticket_status'
function _load() { try { return JSON.parse(localStorage.getItem(KEY) || '{}') } catch { return {} } }
function _persist(s) { try { localStorage.setItem(KEY, JSON.stringify(s)) } catch {} }

// Global singleton ticket status — shared across Withdraw and Tickets components
let _status = _load()
const _listeners = new Set()

function notify() { _listeners.forEach(fn => fn({ ..._status })) }

export function setTicketStatusGlobal(commitment, value) {
  _status = { ..._status, [commitment]: value }
  _persist(_status)
  notify()
}

export function getTicketStatus() { return _status }

export function setTicketStatusBatch(map) {
  _status = { ..._status, ...map }
  _persist(_status)
  notify()
}

export function useTicketStatus() {
  const [status, setStatus] = useState(_status)
  useEffect(() => {
    setStatus({ ..._status })
    _listeners.add(setStatus)
    return () => _listeners.delete(setStatus)
  }, [])
  return status
}
